UPDATE certifying_bodies SET description='Jabatan Kemajuan Islam Malaysia — the Malaysian government authority behind MS 1500:2019. Its halal certificate is the most widely recognised in the world and a common import requirement across the Middle East and ASEAN.', updated_at=1788900000 WHERE id='jakim';
