UPDATE certifying_bodies SET description='Majlis Ugama Islam Singapura — Singapore''s Islamic Religious Council. It runs a voluntary certification scheme (MUIS-HC-S001) trusted well beyond the city-state; many buyers treat MUIS certification as a premium signal.', updated_at=1788900000 WHERE id='muis';
