UPDATE certifying_bodies SET description='Islamic Food and Nutrition Council of America — the best-known US halal certifier. IFANCA certificates are accepted by JAKIM, MUI and Gulf authorities, making it the default choice for North American exporters.', updated_at=1788900000 WHERE id='ifanca';
