UPDATE certifying_bodies SET description='Pakistan Halal Authority — the federal body developing Pakistan''s formal halal certification infrastructure around PS OIC/SMIIC standards, alongside a fast-growing meat export sector.', updated_at=1788900000 WHERE id='pha';
